import { describe, expect, it } from "vitest";
import {
  postgresIndexOrderingMigration,
  withLegacyPostgresIndexOrdering,
} from "./postgres-index-ordering.js";

const tables = `CREATE TABLE "entries" (
  "id" bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "optional" text COLLATE "C" DEFAULT 'NOT NULL',
  "required" text COLLATE "C" NOT NULL
);`;
const indexes = `CREATE INDEX "partial" ON "entries" (("optional") ASC, ("required") DESC) WHERE "optional" IS NOT NULL AND "required" <> '("optional") ASC)';
CREATE INDEX "required" ON "entries" (("required") DESC, ("id") ASC);`;

describe("historical PostgreSQL index policies", () => {
  it("restores nullable keys without rewriting required keys or quoted data", () => {
    const previous = withLegacyPostgresIndexOrdering(indexes, "schema-nullability", tables);
    expect(previous).toContain('(("optional") ASC NULLS FIRST, ("required") DESC)');
    expect(previous).toContain(`"required" <> '("optional") ASC)'`);
    expect(previous).toContain(
      'CREATE INDEX "required" ON "entries" (("required") DESC, ("id") ASC);',
    );
    expect(withLegacyPostgresIndexOrdering(`${tables}\n${indexes}`)).toContain(
      '(("optional") ASC NULLS FIRST, ("required") DESC NULLS LAST)',
    );
  });

  it("rebuilds only indexes changed since the schema-nullability policy", () => {
    const migration = postgresIndexOrderingMigration(`${tables}\n${indexes}`, "schema-nullability");
    expect(migration).toContain('DROP INDEX "partial";');
    expect(migration).not.toContain('DROP INDEX "required";');
  });
});
